const body = $input.first().json.body;

// Get the tool call data
const toolCall = body.message.toolCalls[0];
const functionName = toolCall.function.name;
const toolCallId = toolCall.id;
const args = toolCall.function.arguments;

const timestamp = new Date().toLocaleString("en-NG", { timeZone: "Africa/Lagos" });

return [{
  json: {
    // Routing — Switch node uses this
    function_name: functionName,
    tool_call_id: toolCallId,

    // Shared fields
    customer_name: args.customer_name || "Unknown",
    phone_number: args.phone_number || "Unknown",
    timestamp: timestamp,

    // Order fields
    order_details: args.order_details || "N/A",
    delivery_or_pickup: args.delivery_or_pickup || "N/A",
    delivery_address: args.delivery_address || "N/A",
    total_estimate: args.total_estimate || 0,
    payment_method: args.payment_method || "N/A",

    // Reservation fields
    party_size: args.party_size || "N/A",
    date_and_time: args.date_and_time || "N/A",
    special_requests: args.special_requests || "N/A",

    // Catering fields
    event_type: args.event_type || "N/A",
    event_date: args.event_date || "N/A",

    customer_question: args.customer_question || "N/A",

    // Callback fields
    issue: args.issue || "N/A",
    status: args.status || "pending_callback"
  }
}];

